window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9b3eda896b04ddb8"]={"versions": [{"id": "FIG-9b3eda896b04ddb8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm nach der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung eines einzelnen Arbeitsschritts im Build- und Generierungsprozess von Basissoftware (BSW). Das Diagramm beschreibt die Übersetzung generierter BSW-Konfigurations-Quelldateien in binären Objektcode innerhalb der klassischen AUTOSAR-Entwicklungskette.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Task):</strong> <code>Compile BSW Configuration Data</code>\n</li><li><strong>Eingangs-Artefakte (<code>«input»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Basic Software Module Core Header</code> (Kardinalität: 1)\n</li><li><code>BSW Module Configuration Data Source Code</code> (Kardinalität: 1)\n</li><li><code>BSW Module Configuration Header File</code> (Kardinalität: 1)\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li><code>BSW Module Configuration Data Object Code</code> (Kardinalität: 1)\n</li></ul>\n</li><li><strong>Werkzeug (<code>«used tool»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Compiler</code> (symbolisiert durch Hammer-Piktogramm)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung der Eingangsdateien: Der statische BSW-Kern-Header (<code>Basic Software Module Core Header</code>), die generierte Quellcodedatei (<code>BSW Module Configuration Data Source Code</code>) sowie die generierte Konfigurations-Headerdatei (<code>BSW Module Configuration Header File</code>) werden der Build-Aktivität zugeführt.\n</li><li>Ausführung: Der <code>Compiler</code> übersetzt den Konfigurationsquellcode unter Einbindung der referenzierten Header-Definitionen.\n</li><li>Ergebnis: Als Artefakt entsteht die kompilierte Objektcodedatei <code>BSW Module Configuration Data Object Code</code> für das jeweilige BSW-Modul.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Schritt trennt die Kompilierung rein konfigurativer Daten (z. B. Post-Build- oder link-time-fähige Datenstrukturen) von der Kompilierung des statischen Modulcodes.\n</li><li>Alle drei Eingangsartefakte sind mit einer Kardinalität von exakt 1 spezifiziert, was die Konsistenz der Modulkonfigurations-Schnittstellen voraussetzt.\n</li><li>Das Ausgangsartefakt geht typischerweise in nachfolgende Link- oder Integrationsschritte auf Steuergeräte-Ebene ein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e21fa4f2c63f7853", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitätsdiagramm nach der AUTOSAR-Methodik (Methodology Activity Diagram) zur Darstellung eines einzelnen Arbeitsschritts im Build- und Generierungsprozess von Basissoftware (BSW). Das Diagramm beschreibt die Übersetzung generierter BSW-Konfigurations-Quelldateien in binären Objektcode innerhalb der klassischen AUTOSAR-Entwicklungskette.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Task):</strong> <code>Compile BSW Configuration Data</code>\n</li><li><strong>Eingangs-Artefakte (<code>«input»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Basic Software Module Core Header</code> (Kardinalität: 1)\n</li><li><code>BSW Module Configuration Data Source Code</code> (Kardinalität: 1)\n</li><li><code>BSW Module Configuration Header File</code> (Kardinalität: 1)\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li><code>BSW Module Configuration Data Object Code</code> (Kardinalität: 1)\n</li></ul>\n</li><li><strong>Werkzeug (<code>«used tool»</code>):</strong>\n<ul class=\"fig-list\"><li><code>Compiler</code> (symbolisiert durch Hammer-Piktogramm)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung der Eingangsdateien: Der statische BSW-Kern-Header (<code>Basic Software Module Core Header</code>), die generierte Quellcodedatei (<code>BSW Module Configuration Data Source Code</code>) sowie die generierte Konfigurations-Headerdatei (<code>BSW Module Configuration Header File</code>) werden der Build-Aktivität zugeführt.\n</li><li>Ausführung: Der <code>Compiler</code> übersetzt den Konfigurationsquellcode unter Einbindung der referenzierten Header-Definitionen.\n</li><li>Ergebnis: Als Artefakt entsteht die kompilierte Objektcodedatei <code>BSW Module Configuration Data Object Code</code> für das jeweilige BSW-Modul.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der Schritt trennt die Kompilierung rein konfigurativer Daten (z. B. Post-Build- oder link-time-fähige Datenstrukturen) von der Kompilierung des statischen Modulcodes.\n</li><li>Alle drei Eingangsartefakte sind mit einer Kardinalität von exakt 1 spezifiziert, was die Konsistenz der Modulkonfigurations-Schnittstellen voraussetzt.\n</li><li>Das Ausgangsartefakt geht typischerweise in nachfolgende Link- oder Integrationsschritte auf Steuergeräte-Ebene ein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9b3eda896b04ddb8", "to": "FIG-e21fa4f2c63f7853", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
